begin;
insert into auth.users(id,email,raw_app_meta_data)values('99180000-0000-4000-8000-000000000001','kind-admin@example.invalid','{"role":"admin"}');
insert into public.profiles(id,nickname,city_id,terms_accepted_at,privacy_accepted_at,ai_safety_consent_at,consent_version)values('99180000-0000-4000-8000-000000000001','종류관리검사','vancouver',now(),now(),now(),'test');
insert into auth.sessions(id,user_id,aal)values('99190000-0000-4000-8000-000000000001','99180000-0000-4000-8000-000000000001','aal2');
select set_config('request.jwt.claim.sub','99180000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"99180000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2","session_id":"99190000-0000-4000-8000-000000000001","app_metadata":{"role":"admin"}}',true);
create temporary table merchant_kind_checks(name text,passed boolean) on commit drop;
do $$
declare m private.merchants; sid uuid; bid uuid; pid uuid; rejected boolean; result jsonb; before_paths text[]; source_post uuid;
begin
  perform public.save_admin_merchant_record('business','99170000-0000-4000-8000-000000000001','종류 검사 임대 매물','vancouver','https://www.craigslist.org/view/d/fixture/example','trial','granted','QA rollback',null);
  select array_agg('99180000-0000-4000-8000-000000000001/photo_'||i||'.webp'order by i)into before_paths from generate_series(1,20)i;
  source_post:=public.create_post('vancouver',14::smallint,'매물20장 종류 검사','검증용 매물입니다.',p_image_paths=>before_paths,p_kind=>'listing');
  perform public.link_admin_merchant_post('99170000-0000-4000-8000-000000000001',source_post,'https://www.craigslist.org/view/d/fixture/example');
  insert into merchant_kind_checks values('unclassified_business_profile_was_visible',public.get_merchant_profile('99170000-0000-4000-8000-000000000001')is not null);
  select * into m from private.merchants where id='99170000-0000-4000-8000-000000000001';
  select image_paths into before_paths from public.posts where id=source_post;
  perform public.save_admin_merchant_record('source',m.id,m.name,m.city_id,m.contact,m.status,m.consent,m.consent_note,m.trial_ends_at,m.industry,m.services,m.address);
  insert into merchant_kind_checks values('source_company_profile_hidden',public.get_merchant_profile(m.id) is null);
  insert into merchant_kind_checks values('source_reviews_hidden',public.get_merchant_reviews(source_post) is null);
  insert into merchant_kind_checks values('source_profile_posts_hidden',public.get_merchant_profile_posts(m.id) is null);
  result:=public.get_merchant_post_source(source_post);
  insert into merchant_kind_checks values('source_inquiry_retained',result->>'record_kind'='source' and result->>'original_url'=m.contact);
  insert into merchant_kind_checks values('source_twenty_photos_retained',(select image_paths=before_paths and cardinality(image_paths)=20 from public.posts where id=source_post));
  rejected:=false;begin insert into private.merchant_reviews(merchant_id,author_id,score)values(m.id,auth.uid(),8);exception when others then if sqlerrm='MERCHANT_REVIEWS_UNAVAILABLE'then rejected:=true;else raise;end if;end;
  insert into merchant_kind_checks values('source_review_insert_blocked',rejected);
  sid:=public.save_admin_merchant(null,'종류 검사 기본 대리등록','vancouver','','lead','pending','',null);
  insert into merchant_kind_checks values('legacy_creation_defaults_source',(select record_kind='source'from private.merchants where id=sid));
  bid:=public.save_admin_merchant_record('business',null,'종류 검사 확인된 회사','vancouver','','trial','granted','QA rollback',null);
  pid:=public.create_post('vancouver',17::smallint,'확인 업체 종류 검사','검증용 글입니다.',p_kind=>'listing');
  perform public.link_admin_merchant_post(bid,pid,'https://example.com/inquiry');
  insert into merchant_kind_checks values('business_profile_visible',public.get_merchant_profile(bid) is not null);
  insert into merchant_kind_checks values('business_reviews_available',public.get_merchant_reviews(pid) is not null);
  insert into private.merchant_reviews(merchant_id,author_id,score)values(bid,auth.uid(),8);
  rejected:=false;begin perform public.save_admin_merchant_record('source',bid,'보존 검사 회사','vancouver','','trial','granted','QA rollback',null);exception when others then if sqlerrm='MERCHANT_KIND_HAS_HISTORY'then rejected:=true;else raise;end if;end;
  insert into merchant_kind_checks values('review_assets_block_reclassification',rejected and(select record_kind='business'from private.merchants where id=bid)and(select count(*)=1 from private.merchant_reviews where merchant_id=bid));
  bid:=public.save_admin_merchant_record('business',null,'종류 검사 계정 회사','vancouver','','trial','granted','QA rollback',null);
  update private.merchants set owner_id=auth.uid()where id=bid;
  rejected:=false;begin perform public.save_admin_merchant_record('source',bid,'계정 보존 검사','vancouver','','trial','granted','QA rollback',null);exception when others then if sqlerrm='MERCHANT_KIND_HAS_HISTORY'then rejected:=true;else raise;end if;end;
  insert into merchant_kind_checks values('owner_connection_blocks_reclassification',rejected);
  rejected:=false;begin perform public.save_admin_merchant_record('invalid',null,'오류 검사','vancouver','','trial','granted','QA rollback',null);exception when others then if sqlerrm='INVALID_MERCHANT_KIND'then rejected:=true;else raise;end if;end;
  insert into merchant_kind_checks values('invalid_kind_blocked',rejected);
  insert into merchant_kind_checks values('real_estate_category_identity_retained',(select id=14 and label='부동산'from public.tags where slug='housing'));
  perform set_config('request.jwt.claims','{"sub":"99180000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1","session_id":"99190000-0000-4000-8000-000000000001","app_metadata":{"role":"admin"}}',true);
  rejected:=false;begin perform public.save_admin_merchant_record('business',null,'인증 검사','vancouver','','trial','granted','QA rollback',null);exception when others then if sqlerrm='ADMIN_REQUIRED'then rejected:=true;else raise;end if;end;
  insert into merchant_kind_checks values('aal1_admin_blocked',rejected);
  insert into merchant_kind_checks values('anon_cannot_save',not has_function_privilege('anon','public.save_admin_merchant_record(text,uuid,text,text,text,text,text,text,date,text,text,text)','execute'));
end;$$;
select jsonb_build_object('checks',(select jsonb_agg(x)from merchant_kind_checks x),'passed',(select count(*)from merchant_kind_checks where passed),'failed',(select count(*)from merchant_kind_checks where not passed)) result;
rollback;
